nta.declaration:
/*
*  --------- BEGIN CONFIGURATION SECTION
*/
const bool Periodic = true;

const double Sporadic_Interval = 40.0;

const int MaxTime = 50;
typedef int[0,MaxTime] time_t;

const int Tasks = 3+3;                 // Number of tasks/actors
typedef int[0,Tasks-1] t_id;

const int Procs = 4;                 // Number of resources
typedef int[0,Procs-1] r_id;

const int Dags = 1;                 // Number of resources
typedef int[0,Dags-1] d_id;

const int load_limit[Procs] = {9,9,9,9};

typedef struct {
  bool sporadic;
  int number_tasks;
} dag_t;

typedef struct {
  time_t initial_offset;
  time_t min_period;
  time_t max_period;
  time_t offset;
  time_t deadline;
  time_t bcet;
  time_t wcet;
  r_id resources[Procs-1];
  int pri;
  int[0,1] type; // 0: task node, 1: communication node
  int curr_resource;

} task_t;

const r_id res[Procs-1] = {0,1,2};
const r_id bus[Procs-1] = {3,3,3};
const dag_t dag[Dags] = {
{false, 6}
};

//init_offset, min_period, max_period, offset, deadline, bcet, wcet, resource, priority
task_t task[Dags][Tasks] = {
    {
        {0,20,20,0,15,4,4,res,1,0,0}, /* task 0 */
        {0,20,20,0,15,3,3,res,1,0,0}, /* task 1 */
        {0,20,20,0,15,2,2,res,1,0,0}, /* task 2 */
        {0,20,20,0,15,1,1,bus,1,1,0}, /* edge 0-1 */
        {0,20,20,0,15,1,1,bus,1,1,0}, /* edge 0-2 */
        {0,20,20,0,15,1,1,bus,1,1,0}  /* edge 2-0 */
    }
};

typedef struct {
  int[0,Tasks] length[Dags];
  t_id element[Dags][Tasks];
} buffer_t; 

buffer_t buffer[Procs];

const int Policies      = 3;
const int EDF  		= 0;
const int FIFO 		= 1;
const int FPS  		= 2;

chan inserted, insert_task[Policies];
typedef int[0,Policies-1] policy_t;

/*
* Task graph definition of dependencies
*
* Meaning of Depend[i][j]:
*    - 0/false : task i does not depend on task j
*    - 1/true  : task i depends on task j
*/
int edge_buffer[Dags][Tasks][Tasks] = {
    {
               /*t0,t1,t2, e1,e2,e3*/
    /* task 0 */ { 0, 0, 0, 9, 0, 9},
    /* task 1 */ { 0, 0, 0, 0, 0, 0},
    /* task 2 */ { 0, 0, 0, 0, 0, 0},
    /* edge 1 */ { 0, 0, 0, 0, 0, 0},
    /* edge 2 */ { 12, 0, 0, 0, 0, 0},
    /* edge 3 */ { 0, 3, 0, 0, 0, 0}
    }
};


const int prod[Dags][Tasks][Tasks] = {
    {
                /*t0,t1,t2, e1,e2,e3*/
    /* task 0 */ { 0, 0, 0, 3, 0, 3},
    /* task 1 */ { 0, 0, 0, 0, 0, 0},
    /* task 2 */ { 0, 0, 0, 0, 6, 0},
    /* edge 1 */ { 0, 0, 3, 0, 0, 0},
    /* edge 2 */ { 3, 0, 0, 0, 0, 0},
    /* edge 3 */ { 0, 3, 0, 0, 0, 0}
    }
};

const int cons[Dags][Tasks][Tasks]= {
    {
                /*t0,t1,t2, e1,e2,e3*/
    /* task 0 */ { 0, 0, 0, 3, 0, 3},
    /* task 1 */ { 0, 0, 0, 0, 0, 0},
    /* task 2 */ { 0, 0, 0, 0, 3, 0},
    /* edge 1 */ { 0, 0, 2, 0, 0, 0},
    /* edge 2 */ { 3, 0, 0, 0, 0, 0},
    /* edge 3 */ { 0, 2, 0, 0, 0, 0}
    }
};

/*
*  --------- END CONFIGURATION SECTION
*/
clock time[Dags][Tasks];//, exec[Tasks];
bool complete[Dags][Tasks];
bool fired[Dags][Tasks]; 

/* debug variables */
bool error[Dags][Tasks];
int counter[Dags][Tasks];

urgent chan ready[Procs];
chan finished[Dags][Tasks];//run[Procs+1], stop[Procs], done[Procs];


/*
    processor load tracking
    load[p] = sum of the costs of tasks currently assigned to p
    load_limit[p]
*/
int load[Procs];

meta struct {
  meta t_id task;
  meta r_id resource;
  meta bool preempt;
} param;

void setParams(t_id t, r_id r, bool preempt) {
  param.task = t; param.resource = r; param.preempt = preempt;
}

meta t_id ready_task[Dags];

void insert_at(int[0,Tasks] pos, t_id tid, r_id rid) {
  int i;
  for(i = buffer[rid].length[0]; i > pos; i--) {
    buffer[rid].element[0][i] = buffer[rid].element[0][i-1];
  }
  buffer[rid].element[0][pos] = tid;
  buffer[rid].length[0]++;

}

// to check if an actor 'a' of DAG 'd' can fire
bool can_fire(d_id did, t_id tid)
{
    int i;
    // to fire, all incoming edges must have enough tokens
    for (i = 0; i < Tasks; i++)
    {
        if (cons[did][i][tid] > 0)
        {
            if (edge_buffer[did][i][tid] >= cons[did][i][tid])
            {
                return true;
            }            
        }      
    }
    return false;
}
// consumes tokens from incoming edges and resets the actor's clock
void consume(d_id did, t_id tid)
{
    int i;

    for (i = 0; i < Tasks; i++)
    {
        if (cons[did][i][tid] > 0)
        {
            edge_buffer[did][i][tid] -= cons[did][i][tid];
        }
    }
    // reset clock do actor disparado
    // clk[d][a] = 0;
}
// produces tokens on outgoing edges. Called when an execution completes.
void produce(d_id did, t_id tid)
{
    int i;

    for (i = 0; i < Tasks; i++)
    {
        if (prod[did][tid][i] > 0)
        {
            edge_buffer[did][tid][i] += prod[did][tid][i];  
        }
    }
}

template.declaration:
void removeTask() {
  int i = 0;
  buffer[id].length[0]--;
  do {
    buffer[id].element[0][i] = buffer[id].element[0][i+1];
    i++;
  } while (i < buffer[id].length[0]);
  buffer[id].element[0][buffer[id].length[0]] = 0;
}

t_id front() { return buffer[id].element[0][0]; }

bool empty() {
  return buffer[id].length[0] == 0;
}

clock x;

int resource_pointer;

time_t new_sporadic_period;

bool best_resource_found;

bool dependencies_met() { // deprected - replaced by can_fire(0, id);
  // return forall (j : t_id)  Depend[id][j] imply complete[j];
    return can_fire(0, id);// || first[id] == false;
}

void completed() { //deprected
  complete[0][id] = true;
}

time_t convertToTime(double x) {
    time_t result = 0;

    if (x >= 0) {
        while (x >= result) {
            result = result + 1;
        }
    } else {
        while (x <= result) {
            result = result - 1;
        }
    }

    return result;
}

void new_period() { //deprected

  complete[0][id] = false;

  if (dag[0].sporadic == true)
  {
      int i = 0;
      // for (i = 0; i < dag[0].
// completed[]
      new_sporadic_period = task[0][id].min_period + 1;// convertToTime(random(Sporadic_Interval) + 1);
      task[0][id].max_period = task[0][id].min_period = new_sporadic_period;
  }
}

time_t initialOffset() { return task[0][id].initial_offset; }
time_t minPeriod() { return task[0][id].min_period; }
time_t maxPeriod() { return task[0][id].max_period; }
time_t offset() { return task[0][id].offset; }
time_t deadline() { return task[0][id].deadline; }
time_t BCET() { return task[0][id].bcet; }
time_t WCET() { return task[0][id].wcet; }
time_t priotiry() { return task[0][id].pri; }
r_id resource() { return task[0][id].curr_resource; }

void findBestResource() {
    int best_len = Tasks + 1;
    int i;

    best_resource_found = false;
    task[0][id].curr_resource = -1;

    for (i = 0; i < Procs-1; i++) {
        r_id r = task[0][id].resources[i];

        if (load[r] + task[0][id].wcet <= load_limit[r]) {

            if (buffer[r].length[0] < best_len) {
                best_len = buffer[r].length[0];
                task[0][id].curr_resource = r;
                best_resource_found = true;
            }
        }
    }
}

int[0,1] isRunning() {
  // return (buffer[resource()].element[0] == id? 1 : 0);
  int i;
  for (i = 0; i < Procs-1; i++)
  {
    r_id r = task[0][id].resources[i];
    if (buffer[r].length[0] > 0 && buffer[r].element[0][0] == id)
    {
      return 1;
    }
  }
  return 0;
}

void insert_task_in_buffer() {
  t_id t = param.task;
  r_id r = param.resource;
  int place = (param.preempt ? 0 : 1);
  int i;
  // Find out where to put the task
  while ( place < buffer[r].length[0] && task[0][buffer[r].element[0][place]].pri >= task[0][t].pri ) {
    place++;
  }
  insert_at(place,t,r);
}

int[0,Tasks] place;
t_id tid;
r_id rid;
bool preempt;

void readParameters() {
  tid = param.task; rid = param.resource; preempt = param.preempt;
}

void resetVars() {
  place = tid = rid = 0;
}

nta.system:
//Task id, res. ass., bcet, wcet, deadline, offset, period
// Resource id, preemptive, policy
P0  = Resource(0, false,FPS);
P1  = Resource(1, false,FPS);
P2  = Resource(2, false,FPS);
Bus = Resource(3, false,FIFO);

system Task, P0, P1, Bus, Policy_FPS, Policy_FIFO;
